package cards

import (
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// Suit represents a playing card suit.
type Suit int8

const (
	Spades Suit = iota
	Hearts
	Diamonds
	Clubs
)

func (s Suit) String() string {
	switch s {
	case Spades:
		return "♠"
	case Hearts:
		return "♥"
	case Diamonds:
		return "♦"
	case Clubs:
		return "♣"
	default:
		return "?"
	}
}

// Rank represents the face value of a card.
type Rank int8

const (
	Two Rank = 2 + iota
	Three
	Four
	Five
	Six
	Seven
	Eight
	Nine
	Ten
	Jack
	Queen
	King
	Ace
)

func (r Rank) String() string {
	switch r {
	case Two, Three, Four, Five, Six, Seven, Eight, Nine, Ten:
		return fmt.Sprintf("%d", int(r))
	case Jack:
		return "J"
	case Queen:
		return "Q"
	case King:
		return "K"
	case Ace:
		return "A"
	default:
		return "?"
	}
}

// BlackjackValue returns the standard Blackjack point value (Ace is 11 by default).
func (r Rank) BlackjackValue() int {
	switch r {
	case Two, Three, Four, Five, Six, Seven, Eight, Nine:
		return int(r)
	case Ten, Jack, Queen, King:
		return 10
	case Ace:
		return 11
	default:
		return 0
	}
}

// Card represents a single playing card.
type Card struct {
	Rank Rank
	Suit Suit
}

func NewCard(r Rank, s Suit) Card {
	return Card{Rank: r, Suit: s}
}

func (c Card) String() string {
	return fmt.Sprintf("%s%s", c.Rank.String(), c.Suit.String())
}

// IsTenValue returns true if card has blackjack value of 10 (10, J, Q, K).
func (c Card) IsTenValue() bool {
	return c.Rank.BlackjackValue() == 10
}

// IsAce returns true if card is an Ace.
func (c Card) IsAce() bool {
	return c.Rank == Ace
}

// Shoe represents a multi-deck dealing shoe.
type Shoe struct {
	mu           sync.Mutex
	cards        []Card
	dealtCards   []Card
	totalDecks   int
	cutCardIndex int
	rng          *rand.Rand
	onDeal       func(Card)
}

// ShoeOption defines functional options for Shoe creation.
type ShoeOption func(*Shoe)

// WithCutCardPenetration sets the shoe cut card penetration percentage (e.g. 0.75 = 75%).
func WithCutCardPenetration(penetration float64) ShoeOption {
	return func(s *Shoe) {
		if penetration <= 0 || penetration >= 1.0 {
			penetration = 0.75
		}
		total := s.totalDecks * 52
		s.cutCardIndex = int(float64(total) * penetration)
	}
}

// WithCustomRNG sets a custom random generator (useful for reproducible tests).
func WithCustomRNG(rng *rand.Rand) ShoeOption {
	return func(s *Shoe) {
		s.rng = rng
	}
}

// WithDealListener registers a callback invoked every time a card is dealt.
func WithDealListener(callback func(Card)) ShoeOption {
	return func(s *Shoe) {
		s.onDeal = callback
	}
}

// NewShoe initializes and shuffles a multi-deck shoe (1 to 8 decks).
func NewShoe(numDecks int, opts ...ShoeOption) *Shoe {
	if numDecks < 1 {
		numDecks = 1
	}
	if numDecks > 8 {
		numDecks = 8
	}

	s := &Shoe{
		totalDecks: numDecks,
		rng:        rand.New(rand.NewSource(time.Now().UnixNano())),
	}

	// Default cut card index: 75%
	s.cutCardIndex = int(float64(numDecks*52) * 0.75)

	for _, opt := range opts {
		opt(s)
	}

	s.ResetAndShuffle()
	return s
}

// ResetAndShuffle refills the shoe with full decks and performs a Fisher-Yates shuffle.
func (s *Shoe) ResetAndShuffle() {
	s.mu.Lock()
	defer s.mu.Unlock()

	totalCards := s.totalDecks * 52
	s.cards = make([]Card, 0, totalCards)
	s.dealtCards = make([]Card, 0, totalCards)

	allSuits := []Suit{Spades, Hearts, Diamonds, Clubs}
	allRanks := []Rank{Two, Three, Four, Five, Six, Seven, Eight, Nine, Ten, Jack, Queen, King, Ace}

	for d := 0; d < s.totalDecks; d++ {
		for _, suit := range allSuits {
			for _, rank := range allRanks {
				s.cards = append(s.cards, Card{Rank: rank, Suit: suit})
			}
		}
	}

	// Fisher-Yates shuffle
	for i := len(s.cards) - 1; i > 0; i-- {
		j := s.rng.Intn(i + 1)
		s.cards[i], s.cards[j] = s.cards[j], s.cards[i]
	}
}

// Deal pops the top card from the shoe. If empty, it automatically resets & shuffles.
func (s *Shoe) Deal() Card {
	s.mu.Lock()
	if len(s.cards) == 0 {
		s.mu.Unlock()
		s.ResetAndShuffle()
		s.mu.Lock()
	}

	idx := len(s.cards) - 1
	card := s.cards[idx]
	s.cards = s.cards[:idx]
	s.dealtCards = append(s.dealtCards, card)

	cb := s.onDeal
	s.mu.Unlock()

	if cb != nil {
		cb(card)
	}
	return card
}

// NeedsShuffle returns true if dealt cards count has passed the cut card index.
func (s *Shoe) NeedsShuffle() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.dealtCards) >= s.cutCardIndex
}

// RemainingCards returns the number of un-dealt cards in the shoe.
func (s *Shoe) RemainingCards() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.cards)
}

// DealtCount returns the number of cards dealt so far.
func (s *Shoe) DealtCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.dealtCards)
}

// TotalDecks returns the configured deck count.
func (s *Shoe) TotalDecks() int {
	return s.totalDecks
}

// RemainingDecks returns remaining decks estimated as a float (cards / 52.0).
func (s *Shoe) RemainingDecks() float64 {
	rem := float64(s.RemainingCards()) / 52.0
	if rem < 0.5 {
		return 0.5 // Bound minimum remaining decks to prevent division by zero in card counting
	}
	return rem
}

// Penetration returns the percentage of the shoe dealt (0.0 to 1.0).
func (s *Shoe) Penetration() float64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	total := s.totalDecks * 52
	if total == 0 {
		return 0
	}
	return float64(len(s.dealtCards)) / float64(total)
}

package cards

import (
	"math/rand"
	"testing"
)

func TestCard_StringAndValues(t *testing.T) {
	tests := []struct {
		card     Card
		expected string
		bjVal    int
		isTen    bool
		isAce    bool
	}{
		{NewCard(Ace, Spades), "A♠", 11, false, true},
		{NewCard(King, Hearts), "K♥", 10, true, false},
		{NewCard(Queen, Diamonds), "Q♦", 10, true, false},
		{NewCard(Jack, Clubs), "J♣", 10, true, false},
		{NewCard(Ten, Spades), "10♠", 10, true, false},
		{NewCard(Nine, Hearts), "9♥", 9, false, false},
		{NewCard(Two, Diamonds), "2♦", 2, false, false},
		{NewCard(Rank(99), Suit(99)), "??", 0, false, false},
	}

	for _, tt := range tests {
		if got := tt.card.String(); got != tt.expected {
			t.Errorf("Card.String() = %v, want %v", got, tt.expected)
		}
		if got := tt.card.Rank.BlackjackValue(); got != tt.bjVal {
			t.Errorf("Rank.BlackjackValue() = %v, want %v", got, tt.bjVal)
		}
		if got := tt.card.IsTenValue(); got != tt.isTen {
			t.Errorf("Card.IsTenValue() = %v, want %v", got, tt.isTen)
		}
		if got := tt.card.IsAce(); got != tt.isAce {
			t.Errorf("Card.IsAce() = %v, want %v", got, tt.isAce)
		}
	}
}

func TestShoe_CreationAndDeal(t *testing.T) {
	decks := 6
	dealtList := []Card{}
	rng := rand.New(rand.NewSource(42))

	shoe := NewShoe(
		decks,
		WithCutCardPenetration(0.75),
		WithCustomRNG(rng),
		WithDealListener(func(c Card) {
			dealtList = append(dealtList, c)
		}),
	)

	if shoe.TotalDecks() != 6 {
		t.Fatalf("Expected 6 decks, got %d", shoe.TotalDecks())
	}

	totalCards := 6 * 52
	if shoe.RemainingCards() != totalCards {
		t.Fatalf("Expected %d remaining cards, got %d", totalCards, shoe.RemainingCards())
	}

	if shoe.DealtCount() != 0 {
		t.Fatalf("Expected 0 dealt cards, got %d", shoe.DealtCount())
	}

	c1 := shoe.Deal()
	if shoe.RemainingCards() != totalCards-1 {
		t.Fatalf("Expected %d cards left, got %d", totalCards-1, shoe.RemainingCards())
	}
	if shoe.DealtCount() != 1 {
		t.Fatalf("Expected 1 dealt card, got %d", shoe.DealtCount())
	}
	if len(dealtList) != 1 || dealtList[0] != c1 {
		t.Fatalf("Deal callback did not receive expected card")
	}

	// Test bounds for deck creation (0 -> 1 deck, 10 -> 8 decks)
	s1 := NewShoe(0)
	if s1.TotalDecks() != 1 {
		t.Errorf("Expected 1 deck fallback, got %d", s1.TotalDecks())
	}
	s8 := NewShoe(10, WithCutCardPenetration(1.5))
	if s8.TotalDecks() != 8 {
		t.Errorf("Expected 8 decks max, got %d", s8.TotalDecks())
	}

	// Test Deal until empty triggers reshuffle
	singleShoe := NewShoe(1)
	for i := 0; i < 52; i++ {
		singleShoe.Deal()
	}
	if singleShoe.RemainingCards() != 0 {
		t.Errorf("Expected 0 cards left, got %d", singleShoe.RemainingCards())
	}
	// 53rd deal should auto-reshuffle
	nextCard := singleShoe.Deal()
	if nextCard.Rank < Two || nextCard.Rank > Ace {
		t.Errorf("Invalid card dealt after auto reshuffle: %v", nextCard)
	}
	if singleShoe.RemainingCards() != 51 {
		t.Errorf("Expected 51 cards remaining after auto-reshuffle, got %d", singleShoe.RemainingCards())
	}
}

func TestShoe_PenetrationAndNeedsShuffle(t *testing.T) {
	shoe := NewShoe(1, WithCutCardPenetration(0.5)) // Cut card at 26 cards
	if shoe.NeedsShuffle() {
		t.Errorf("Should not need shuffle initially")
	}

	for i := 0; i < 25; i++ {
		shoe.Deal()
	}
	if shoe.NeedsShuffle() {
		t.Errorf("Should not need shuffle at 25 dealt cards")
	}

	shoe.Deal() // 26th card dealt
	if !shoe.NeedsShuffle() {
		t.Errorf("Expected NeedsShuffle to be true at 26 dealt cards")
	}

	pen := shoe.Penetration()
	if pen < 0.49 || pen > 0.51 {
		t.Errorf("Expected penetration ~0.50, got %f", pen)
	}

	remDecks := shoe.RemainingDecks()
	if remDecks < 0.49 || remDecks > 0.51 {
		t.Errorf("Expected remaining decks ~0.50, got %f", remDecks)
	}
}

func BenchmarkShoeDeal(b *testing.B) {
	shoe := NewShoe(6)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_ = shoe.Deal()
	}
}

func BenchmarkShoeShuffle(b *testing.B) {
	shoe := NewShoe(6)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		shoe.ResetAndShuffle()
	}
}

package rules

import "fmt"

// BlackjackPayout represents the payout multiplier on a winning natural Blackjack.
type BlackjackPayout float64

const (
	Payout3to2 BlackjackPayout = 1.5 // 3:2 payout (standard/favorable)
	Payout6to5 BlackjackPayout = 1.2 // 6:5 payout (high house edge)
	Payout1to1 BlackjackPayout = 1.0 // 1:1 payout (single deck / variant)
)

func (p BlackjackPayout) String() string {
	switch p {
	case Payout3to2:
		return "3:2"
	case Payout6to5:
		return "6:5"
	case Payout1to1:
		return "1:1"
	default:
		return fmt.Sprintf("%.2f:1", float64(p))
	}
}

// SurrenderRule specifies the surrender availability.
type SurrenderRule int

const (
	SurrenderNone SurrenderRule = iota
	SurrenderLate               // Surrender after dealer peeks for BJ
	SurrenderEarly              // Surrender before dealer peeks for BJ
)

func (s SurrenderRule) String() string {
	switch s {
	case SurrenderNone:
		return "None"
	case SurrenderLate:
		return "Late Surrender"
	case SurrenderEarly:
		return "Early Surrender"
	default:
		return "Unknown"
	}
}

// DoubleRestriction specifies on what hand totals doubling is permitted.
type DoubleRestriction int

const (
	DoubleAny2Cards DoubleRestriction = iota
	Double9To11Only
	Double10Or11Only
)

func (d DoubleRestriction) String() string {
	switch d {
	case DoubleAny2Cards:
		return "Any 2 Cards"
	case Double9To11Only:
		return "9, 10, or 11 only"
	case Double10Or11Only:
		return "10 or 11 only"
	default:
		return "Unknown"
	}
}

// RuleSet encapsulates all casino table rules and parameters.
type RuleSet struct {
	Name                 string
	Decks                int
	DealerHitsSoft17     bool              // true = H17, false = S17
	BlackjackPayout      BlackjackPayout   // 3:2 or 6:5
	DoubleAfterSplit     bool              // DAS
	DoubleRestriction    DoubleRestriction // Any 2, 9-11, 10-11
	MaxSplitHands        int               // Max resulting hands (e.g., 4 = split up to 3 times)
	ResplitAces          bool              // Can split Aces more than once
	HitSplitAces         bool              // Can draw multiple cards to split Aces
	Surrender            SurrenderRule     // Late / Early / None
	DealerPeeksHoleCard  bool              // US Peek on Ace/10 vs European No-Hole-Card (ENHC)
	InsuranceOffered     bool              // Pays 2:1 on dealer Ace
	DeckPenetration      float64           // Shoe penetration cut card (e.g., 0.75)
}

// VegasStrip returns the standard Vegas Strip casino ruleset (4 decks, S17, 3:2, DAS, US Peek, Late Surrender).
func VegasStrip() RuleSet {
	return RuleSet{
		Name:                "Vegas Strip",
		Decks:               4,
		DealerHitsSoft17:    false, // S17
		BlackjackPayout:     Payout3to2,
		DoubleAfterSplit:    true,
		DoubleRestriction:   DoubleAny2Cards,
		MaxSplitHands:       4,
		ResplitAces:         false,
		HitSplitAces:        false,
		Surrender:           SurrenderLate,
		DealerPeeksHoleCard: true,
		InsuranceOffered:    true,
		DeckPenetration:     0.75,
	}
}

// AtlanticCity returns Atlantic City ruleset (8 decks, S17, 3:2, DAS, US Peek, Late Surrender, Resplit to 4 hands).
func AtlanticCity() RuleSet {
	return RuleSet{
		Name:                "Atlantic City",
		Decks:               8,
		DealerHitsSoft17:    false, // S17
		BlackjackPayout:     Payout3to2,
		DoubleAfterSplit:    true,
		DoubleRestriction:   DoubleAny2Cards,
		MaxSplitHands:       4,
		ResplitAces:         true,
		HitSplitAces:        false,
		Surrender:           SurrenderLate,
		DealerPeeksHoleCard: true,
		InsuranceOffered:    true,
		DeckPenetration:     0.75,
	}
}

// European returns European Blackjack ruleset (2 decks, S17, 3:2, ENHC - No Hole Card Peek, Double on 9-11 only, No Surrender).
func European() RuleSet {
	return RuleSet{
		Name:                "European",
		Decks:               2,
		DealerHitsSoft17:    false, // S17
		BlackjackPayout:     Payout3to2,
		DoubleAfterSplit:    false,
		DoubleRestriction:   Double9To11Only,
		MaxSplitHands:       2,
		ResplitAces:         false,
		HitSplitAces:        false,
		Surrender:           SurrenderNone,
		DealerPeeksHoleCard: false, // ENHC
		InsuranceOffered:    true,
		DeckPenetration:     0.65,
	}
}

// SingleDeckVegas returns Single Deck Vegas Downtown ruleset (1 deck, H17, 3:2 or 6:5, No DAS).
func SingleDeckVegas(payout BlackjackPayout) RuleSet {
	return RuleSet{
		Name:                "Single Deck Vegas",
		Decks:               1,
		DealerHitsSoft17:    true, // H17
		BlackjackPayout:     payout,
		DoubleAfterSplit:    false,
		DoubleRestriction:   DoubleAny2Cards,
		MaxSplitHands:       2,
		ResplitAces:         false,
		HitSplitAces:        false,
		Surrender:           SurrenderNone,
		DealerPeeksHoleCard: true,
		InsuranceOffered:    true,
		DeckPenetration:     0.60,
	}
}

// Validate ensures rules are physically and logically consistent.
func (r *RuleSet) Validate() error {
	if r.Decks < 1 || r.Decks > 8 {
		return fmt.Errorf("deck count must be between 1 and 8, got %d", r.Decks)
	}
	if r.BlackjackPayout <= 0 {
		return fmt.Errorf("blackjack payout must be positive, got %v", r.BlackjackPayout)
	}
	if r.MaxSplitHands < 1 {
		return fmt.Errorf("max split hands must be >= 1, got %d", r.MaxSplitHands)
	}
	if r.DeckPenetration <= 0 || r.DeckPenetration >= 1.0 {
		r.DeckPenetration = 0.75
	}
	return nil
}

package rules

import "testing"

func TestRulePresetsAndStrings(t *testing.T) {
	vegas := VegasStrip()
	if err := vegas.Validate(); err != nil {
		t.Fatalf("VegasStrip validation failed: %v", err)
	}
	if vegas.DealerHitsSoft17 {
		t.Errorf("VegasStrip should be S17")
	}
	if vegas.Decks != 4 {
		t.Errorf("VegasStrip decks expected 4, got %d", vegas.Decks)
	}

	ac := AtlanticCity()
	if err := ac.Validate(); err != nil {
		t.Fatalf("AtlanticCity validation failed: %v", err)
	}
	if !ac.ResplitAces {
		t.Errorf("AtlanticCity should allow ResplitAces")
	}

	euro := European()
	if err := euro.Validate(); err != nil {
		t.Fatalf("European validation failed: %v", err)
	}
	if euro.DealerPeeksHoleCard {
		t.Errorf("European should be ENHC (no hole card peek)")
	}
	if euro.DoubleRestriction != Double9To11Only {
		t.Errorf("European should restrict double to 9-11")
	}

	single32 := SingleDeckVegas(Payout3to2)
	if err := single32.Validate(); err != nil {
		t.Fatalf("SingleDeckVegas 3:2 validation failed: %v", err)
	}
	if !single32.DealerHitsSoft17 {
		t.Errorf("SingleDeckVegas should be H17")
	}

	single65 := SingleDeckVegas(Payout6to5)
	if single65.BlackjackPayout != Payout6to5 {
		t.Errorf("Expected 6:5 payout")
	}

	// Test String() methods
	if Payout3to2.String() != "3:2" || Payout6to5.String() != "6:5" || Payout1to1.String() != "1:1" || BlackjackPayout(2.0).String() != "2.00:1" {
		t.Errorf("Unexpected Payout string representation")
	}

	if SurrenderNone.String() != "None" || SurrenderLate.String() != "Late Surrender" || SurrenderEarly.String() != "Early Surrender" || SurrenderRule(99).String() != "Unknown" {
		t.Errorf("Unexpected Surrender string representation")
	}

	if DoubleAny2Cards.String() != "Any 2 Cards" || Double9To11Only.String() != "9, 10, or 11 only" || Double10Or11Only.String() != "10 or 11 only" || DoubleRestriction(99).String() != "Unknown" {
		t.Errorf("Unexpected DoubleRestriction string representation")
	}
}

func TestRuleSet_ValidationErrors(t *testing.T) {
	r := VegasStrip()

	r.Decks = 0
	if err := r.Validate(); err == nil {
		t.Errorf("Expected error for 0 decks")
	}

	r.Decks = 9
	if err := r.Validate(); err == nil {
		t.Errorf("Expected error for 9 decks")
	}

	r.Decks = 6
	r.BlackjackPayout = 0
	if err := r.Validate(); err == nil {
		t.Errorf("Expected error for 0 payout")
	}

	r.BlackjackPayout = Payout3to2
	r.MaxSplitHands = 0
	if err := r.Validate(); err == nil {
		t.Errorf("Expected error for 0 max split hands")
	}

	r.MaxSplitHands = 4
	r.DeckPenetration = 0
	_ = r.Validate()
	if r.DeckPenetration != 0.75 {
		t.Errorf("Expected penetration default fallback to 0.75, got %f", r.DeckPenetration)
	}
}

package engine

import (
	"blackjack/pkg/cards"
	"fmt"
)

// HandStatus represents the current state of a hand.
type HandStatus int

const (
	StatusInPlay HandStatus = iota
	StatusStood
	StatusDoubled
	StatusBusted
	StatusBlackjack
	StatusSurrendered
)

func (s HandStatus) String() string {
	switch s {
	case StatusInPlay:
		return "In Play"
	case StatusStood:
		return "Stood"
	case StatusDoubled:
		return "Doubled"
	case StatusBusted:
		return "Busted"
	case StatusBlackjack:
		return "Blackjack"
	case StatusSurrendered:
		return "Surrendered"
	default:
		return "Unknown"
	}
}

// Hand represents a single blackjack hand.
type Hand struct {
	Cards          []cards.Card
	Bet            float64
	Status         HandStatus
	IsSplitHand    bool
	FromSplitAces  bool
	Doubled        bool
	InsuranceBet   float64
	InsuranceWon   bool
	Payout         float64 // Net payout multiplier (e.g. +1.5 for BJ, -1.0 for loss, 0 for push)
	NetProfit      float64 // Total net currency profit/loss for this hand
}

// NewHand creates an empty hand with initial wager.
func NewHand(bet float64) *Hand {
	return &Hand{
		Cards:  make([]cards.Card, 0, 8),
		Bet:    bet,
		Status: StatusInPlay,
	}
}

// AddCard appends a card to the hand.
func (h *Hand) AddCard(c cards.Card) {
	h.Cards = append(h.Cards, c)
}

// Score computes the best total value and whether the hand is soft (contains an Ace counted as 11).
func (h *Hand) Score() (total int, isSoft bool) {
	aces := 0
	sum := 0

	for _, c := range h.Cards {
		if c.IsAce() {
			aces++
			sum += 11
		} else {
			sum += c.Rank.BlackjackValue()
		}
	}

	for sum > 21 && aces > 0 {
		sum -= 10
		aces--
	}

	return sum, (aces > 0)
}

// Total returns just the integer score.
func (h *Hand) Total() int {
	t, _ := h.Score()
	return t
}

// IsBusted returns true if hand total exceeds 21.
func (h *Hand) IsBusted() bool {
	return h.Total() > 21
}

// IsBlackjack returns true if initial 2 cards equal 21 (and not split hand).
func (h *Hand) IsBlackjack() bool {
	if h.IsSplitHand {
		return false // Split 21 is a 21, not a natural Blackjack
	}
	if len(h.Cards) != 2 {
		return false
	}
	return h.Total() == 21
}

// CanSplit returns true if hand has exactly 2 cards of equal point value.
func (h *Hand) CanSplit() bool {
	if len(h.Cards) != 2 {
		return false
	}
	return h.Cards[0].Rank.BlackjackValue() == h.Cards[1].Rank.BlackjackValue()
}

// CanDouble returns true if hand has exactly 2 cards and is in play.
func (h *Hand) CanDouble() bool {
	return len(h.Cards) == 2 && h.Status == StatusInPlay
}

// CanSurrender returns true if hand has exactly 2 cards and has not doubled/split.
func (h *Hand) CanSurrender() bool {
	return len(h.Cards) == 2 && h.Status == StatusInPlay && !h.IsSplitHand
}

// String provides a human-readable representation of the hand.
func (h *Hand) String() string {
	val, soft := h.Score()
	softStr := ""
	if soft && val < 21 {
		softStr = " (soft)"
	}
	var cardStrs string
	for _, c := range h.Cards {
		cardStrs += c.String() + " "
	}
	return fmt.Sprintf("[%s] Total: %d%s - %s (Bet: $%.2f)", cardStrs, val, softStr, h.Status.String(), h.Bet)
}

package engine

import (
	"blackjack/pkg/cards"
	"blackjack/pkg/rules"
	"errors"
	"fmt"
)

// GameState represents the current step in a Blackjack round.
type GameState int

const (
	StateWaitingBet GameState = iota
	StateInsuranceOffered
	StatePlayerTurn
	StateDealerTurn
	StateRoundResolved
)

func (s GameState) String() string {
	switch s {
	case StateWaitingBet:
		return "Waiting For Bet"
	case StateInsuranceOffered:
		return "Insurance Offered"
	case StatePlayerTurn:
		return "Player Turn"
	case StateDealerTurn:
		return "Dealer Turn"
	case StateRoundResolved:
		return "Round Resolved"
	default:
		return "Unknown State"
	}
}

// PlayerAction represents an action chosen by the player.
type PlayerAction int

const (
	ActionHit PlayerAction = iota
	ActionStand
	ActionDouble
	ActionSplit
	ActionSurrender
	ActionInsuranceAccept
	ActionInsuranceDecline
)

func (a PlayerAction) String() string {
	switch a {
	case ActionHit:
		return "Hit"
	case ActionStand:
		return "Stand"
	case ActionDouble:
		return "Double Down"
	case ActionSplit:
		return "Split"
	case ActionSurrender:
		return "Surrender"
	case ActionInsuranceAccept:
		return "Insurance Accept"
	case ActionInsuranceDecline:
		return "Insurance Decline"
	default:
		return "Unknown Action"
	}
}

// GameEngine orchestrates a Blackjack table with deterministic state transitions.
type GameEngine struct {
	Rules          rules.RuleSet
	Shoe           *cards.Shoe
	State          GameState
	DealerHand     *Hand
	PlayerHands    []*Hand
	ActiveHandIdx  int
	DealerHoleCard cards.Card
	HasHoleCard    bool
	InitialBet     float64
}

// NewGameEngine creates a new game engine instance with the specified rules and shoe.
func NewGameEngine(ruleSet rules.RuleSet, shoe *cards.Shoe) *GameEngine {
	if shoe == nil {
		shoe = cards.NewShoe(ruleSet.Decks, cards.WithCutCardPenetration(ruleSet.DeckPenetration))
	}
	return &GameEngine{
		Rules:         ruleSet,
		Shoe:          shoe,
		State:         StateWaitingBet,
		PlayerHands:   make([]*Hand, 0, 4),
		DealerHand:    NewHand(0),
		ActiveHandIdx: 0,
	}
}

// StartRound places initial bet and deals the opening cards.
func (g *GameEngine) StartRound(bet float64) error {
	if bet <= 0 {
		return errors.New("bet must be greater than 0")
	}
	if g.State != StateWaitingBet && g.State != StateRoundResolved {
		return fmt.Errorf("cannot start round in state: %s", g.State)
	}

	if g.Shoe.NeedsShuffle() {
		g.Shoe.ResetAndShuffle()
	}

	g.InitialBet = bet
	g.PlayerHands = []*Hand{NewHand(bet)}
	g.ActiveHandIdx = 0
	g.DealerHand = NewHand(0)
	g.HasHoleCard = false

	// Initial deal: Player, Dealer Upcard, Player, Dealer Hole Card (if US Peek / standard)
	pCard1 := g.Shoe.Deal()
	g.PlayerHands[0].AddCard(pCard1)

	dCard1 := g.Shoe.Deal()
	g.DealerHand.AddCard(dCard1)

	pCard2 := g.Shoe.Deal()
	g.PlayerHands[0].AddCard(pCard2)

	if g.Rules.DealerPeeksHoleCard {
		g.DealerHoleCard = g.Shoe.Deal()
		g.HasHoleCard = true
	}

	// Check for Dealer Ace (Insurance offer)
	if dCard1.IsAce() && g.Rules.InsuranceOffered {
		g.State = StateInsuranceOffered
		return nil
	}

	// If no insurance, check dealer peek / immediate Blackjack
	return g.proceedAfterInsurance()
}

// Insurance responds to insurance offer.
func (g *GameEngine) Insurance(accept bool) error {
	if g.State != StateInsuranceOffered {
		return errors.New("insurance is not currently offered")
	}

	if accept {
		// Insurance costs 0.5x original bet
		insBet := g.InitialBet * 0.5
		g.PlayerHands[0].InsuranceBet = insBet
	}

	return g.proceedAfterInsurance()
}

func (g *GameEngine) proceedAfterInsurance() error {
	dealerHasBJ := false
	if g.HasHoleCard {
		// Test if dealer has Blackjack with hole card
		dScore := g.DealerHand.Cards[0].Rank.BlackjackValue() + g.DealerHoleCard.Rank.BlackjackValue()
		if dScore == 21 {
			dealerHasBJ = true
		}
	}

	// Process insurance win/loss if dealer has BJ
	if g.PlayerHands[0].InsuranceBet > 0 {
		if dealerHasBJ {
			g.PlayerHands[0].InsuranceWon = true
		}
	}

	if dealerHasBJ {
		// Reveal hole card and resolve immediately
		g.DealerHand.AddCard(g.DealerHoleCard)
		g.HasHoleCard = false
		g.DealerHand.Status = StatusBlackjack

		if g.PlayerHands[0].IsBlackjack() {
			g.PlayerHands[0].Status = StatusBlackjack
		} else {
			g.PlayerHands[0].Status = StatusStood
		}
		g.resolveRound()
		return nil
	}

	// Dealer does not have BJ (or ENHC mode where dealer hasn't drawn 2nd card)
	if g.PlayerHands[0].IsBlackjack() {
		g.PlayerHands[0].Status = StatusBlackjack
		// Dealer plays out or round resolves
		g.State = StateDealerTurn
		return g.playDealerTurn()
	}

	g.State = StatePlayerTurn
	g.ActiveHandIdx = 0
	return nil
}

// AvailableActions returns the list of valid actions for the active player hand.
func (g *GameEngine) AvailableActions() []PlayerAction {
	if g.State != StatePlayerTurn {
		if g.State == StateInsuranceOffered {
			return []PlayerAction{ActionInsuranceAccept, ActionInsuranceDecline}
		}
		return nil
	}

	hand := g.ActiveHand()
	if hand == nil || hand.Status != StatusInPlay {
		return nil
	}

	actions := []PlayerAction{ActionHit, ActionStand}

	// Double Down
	if hand.CanDouble() {
		canDoubleRule := true
		if hand.IsSplitHand && !g.Rules.DoubleAfterSplit {
			canDoubleRule = false
		}
		if canDoubleRule {
			tot := hand.Total()
			switch g.Rules.DoubleRestriction {
			case rules.Double9To11Only:
				if tot < 9 || tot > 11 {
					canDoubleRule = false
				}
			case rules.Double10Or11Only:
				if tot < 10 || tot > 11 {
					canDoubleRule = false
				}
			}
		}
		if canDoubleRule {
			actions = append(actions, ActionDouble)
		}
	}

	// Split
	if hand.CanSplit() && len(g.PlayerHands) < g.Rules.MaxSplitHands {
		if hand.Cards[0].IsAce() {
			// Ace splitting restrictions
			if !hand.IsSplitHand || g.Rules.ResplitAces {
				actions = append(actions, ActionSplit)
			}
		} else {
			actions = append(actions, ActionSplit)
		}
	}

	// Surrender
	if hand.CanSurrender() && g.Rules.Surrender == rules.SurrenderLate {
		actions = append(actions, ActionSurrender)
	}

	return actions
}

// ActiveHand returns the pointer to currently active player hand.
func (g *GameEngine) ActiveHand() *Hand {
	if g.ActiveHandIdx >= 0 && g.ActiveHandIdx < len(g.PlayerHands) {
		return g.PlayerHands[g.ActiveHandIdx]
	}
	return nil
}

// Step applies a player action to the active hand.
func (g *GameEngine) Step(action PlayerAction) error {
	if g.State != StatePlayerTurn {
		if g.State == StateInsuranceOffered {
			if action == ActionInsuranceAccept {
				return g.Insurance(true)
			} else if action == ActionInsuranceDecline {
				return g.Insurance(false)
			}
		}
		return fmt.Errorf("action %s not allowed in state %s", action, g.State)
	}

	hand := g.ActiveHand()
	if hand == nil || hand.Status != StatusInPlay {
		return errors.New("no active hand in play")
	}

	switch action {
	case ActionHit:
		return g.actionHit(hand)
	case ActionStand:
		return g.actionStand(hand)
	case ActionDouble:
		return g.actionDouble(hand)
	case ActionSplit:
		return g.actionSplit(hand)
	case ActionSurrender:
		return g.actionSurrender(hand)
	default:
		return fmt.Errorf("invalid action: %s", action)
	}
}

func (g *GameEngine) actionHit(hand *Hand) error {
	card := g.Shoe.Deal()
	hand.AddCard(card)

	if hand.IsBusted() {
		hand.Status = StatusBusted
		return g.advanceToNextHand()
	}

	if hand.Total() == 21 {
		hand.Status = StatusStood
		return g.advanceToNextHand()
	}

	return nil
}

func (g *GameEngine) actionStand(hand *Hand) error {
	hand.Status = StatusStood
	return g.advanceToNextHand()
}

func (g *GameEngine) actionDouble(hand *Hand) error {
	if !hand.CanDouble() {
		return errors.New("cannot double this hand")
	}

	hand.Bet *= 2
	hand.Doubled = true
	card := g.Shoe.Deal()
	hand.AddCard(card)

	if hand.IsBusted() {
		hand.Status = StatusBusted
	} else {
		hand.Status = StatusDoubled
	}

	return g.advanceToNextHand()
}

func (g *GameEngine) actionSplit(hand *Hand) error {
	if !hand.CanSplit() || len(g.PlayerHands) >= g.Rules.MaxSplitHands {
		return errors.New("cannot split this hand")
	}

	isAceSplit := hand.Cards[0].IsAce()
	card1 := hand.Cards[0]
	card2 := hand.Cards[1]

	// First hand keeps card1, draws 1 new card
	hand.Cards = []cards.Card{card1}
	hand.IsSplitHand = true
	if isAceSplit {
		hand.FromSplitAces = true
	}
	newCard1 := g.Shoe.Deal()
	hand.AddCard(newCard1)

	// Create second hand with card2, draws 1 new card
	newHand := NewHand(hand.Bet)
	newHand.Cards = []cards.Card{card2}
	newHand.IsSplitHand = true
	if isAceSplit {
		newHand.FromSplitAces = true
	}
	newCard2 := g.Shoe.Deal()
	newHand.AddCard(newCard2)

	// Insert second hand right after current hand
	g.PlayerHands = append(g.PlayerHands[:g.ActiveHandIdx+1], append([]*Hand{newHand}, g.PlayerHands[g.ActiveHandIdx+1:]...)...)

	// If splitting Aces and rule prohibits hitting split Aces, both stand automatically
	if isAceSplit && !g.Rules.HitSplitAces {
		hand.Status = StatusStood
		newHand.Status = StatusStood
		return g.advanceToNextHand()
	}

	// If hand total is 21 after receiving card, auto stand
	if hand.Total() == 21 {
		hand.Status = StatusStood
		return g.advanceToNextHand()
	}

	return nil
}

func (g *GameEngine) actionSurrender(hand *Hand) error {
	if !hand.CanSurrender() || g.Rules.Surrender != rules.SurrenderLate {
		return errors.New("surrender is not permitted")
	}

	hand.Status = StatusSurrendered
	return g.advanceToNextHand()
}

func (g *GameEngine) advanceToNextHand() error {
	for i := g.ActiveHandIdx; i < len(g.PlayerHands); i++ {
		if g.PlayerHands[i].Status == StatusInPlay {
			g.ActiveHandIdx = i
			return nil
		}
	}

	// All player hands resolved
	g.State = StateDealerTurn
	return g.playDealerTurn()
}

func (g *GameEngine) playDealerTurn() error {
	// Reveal hole card if present
	if g.HasHoleCard {
		g.DealerHand.AddCard(g.DealerHoleCard)
		g.HasHoleCard = false
	}

	// Check if all player hands busted or surrendered - if so, dealer doesn't need to draw
	allDead := true
	for _, h := range g.PlayerHands {
		if h.Status != StatusBusted && h.Status != StatusSurrendered {
			allDead = false
			break
		}
	}

	if !allDead {
		for {
			tot, isSoft := g.DealerHand.Score()
			if tot < 17 {
				c := g.Shoe.Deal()
				g.DealerHand.AddCard(c)
				continue
			}
			if tot == 17 && isSoft && g.Rules.DealerHitsSoft17 {
				c := g.Shoe.Deal()
				g.DealerHand.AddCard(c)
				continue
			}
			break
		}
	}

	if g.DealerHand.IsBusted() {
		g.DealerHand.Status = StatusBusted
	} else if g.DealerHand.IsBlackjack() {
		g.DealerHand.Status = StatusBlackjack
	} else {
		g.DealerHand.Status = StatusStood
	}

	g.resolveRound()
	return nil
}

func (g *GameEngine) resolveRound() {
	g.State = StateRoundResolved
	dealerTotal := g.DealerHand.Total()
	dealerBJ := g.DealerHand.IsBlackjack()
	dealerBust := g.DealerHand.IsBusted()

	for _, h := range g.PlayerHands {
		pTotal := h.Total()
		pBJ := h.IsBlackjack()

		var netProfit float64
		var payout float64

		// Process Insurance
		if h.InsuranceBet > 0 {
			if h.InsuranceWon {
				netProfit += h.InsuranceBet * 2.0 // Insurance pays 2:1
			} else {
				netProfit -= h.InsuranceBet
			}
		}

		if h.Status == StatusSurrendered {
			payout = -0.5
			netProfit += -0.5 * h.Bet
		} else if h.Status == StatusBusted {
			payout = -1.0
			netProfit += -1.0 * h.Bet
		} else if dealerBJ {
			if pBJ {
				payout = 0.0 // Push
				netProfit += 0.0
			} else {
				payout = -1.0
				netProfit += -1.0 * h.Bet
			}
		} else if pBJ {
			// Natural player Blackjack wins payout ratio (e.g. 1.5x)
			bjMultiplier := float64(g.Rules.BlackjackPayout)
			payout = bjMultiplier
			netProfit += bjMultiplier * h.Bet
		} else if dealerBust {
			// Dealer busted, player not busted
			payout = 1.0
			netProfit += 1.0 * h.Bet
		} else {
			// Compare totals
			if pTotal > dealerTotal {
				payout = 1.0
				netProfit += 1.0 * h.Bet
			} else if pTotal < dealerTotal {
				payout = -1.0
				netProfit += -1.0 * h.Bet
			} else {
				payout = 0.0 // Push
				netProfit += 0.0
			}
		}

		h.Payout = payout
		h.NetProfit = netProfit
	}
}

// NetRoundProfit returns the aggregate profit/loss across all split hands and insurance.
func (g *GameEngine) NetRoundProfit() float64 {
	var total float64
	for _, h := range g.PlayerHands {
		total += h.NetProfit
	}
	return total
}

package engine

import (
	"blackjack/pkg/cards"
	"blackjack/pkg/rules"
	"testing"
)

// deterministicShoe creates a shoe with predictable deal order
type fixedShoe struct {
	cards []cards.Card
	idx   int
}

func newFixedShoe(c []cards.Card) *cards.Shoe {
	s := cards.NewShoe(1)
	return s
}

func TestHandScoring(t *testing.T) {
	tests := []struct {
		name         string
		cardsList    []cards.Card
		wantTotal    int
		wantSoft     bool
		wantBJ       bool
		wantBust     bool
		wantCanSplit bool
	}{
		{
			name:         "Natural Blackjack A + K",
			cardsList:    []cards.Card{cards.NewCard(cards.Ace, cards.Spades), cards.NewCard(cards.King, cards.Hearts)},
			wantTotal:    21,
			wantSoft:     true,
			wantBJ:       true,
			wantBust:     false,
			wantCanSplit: false,
		},
		{
			name:         "Pair of 8s",
			cardsList:    []cards.Card{cards.NewCard(cards.Eight, cards.Clubs), cards.NewCard(cards.Eight, cards.Diamonds)},
			wantTotal:    16,
			wantSoft:     false,
			wantBJ:       false,
			wantBust:     false,
			wantCanSplit: true,
		},
		{
			name:         "Ten and Jack pair value split",
			cardsList:    []cards.Card{cards.NewCard(cards.Ten, cards.Clubs), cards.NewCard(cards.Jack, cards.Diamonds)},
			wantTotal:    20,
			wantSoft:     false,
			wantBJ:       false,
			wantBust:     false,
			wantCanSplit: true,
		},
		{
			name:         "Soft 18 (A + 7)",
			cardsList:    []cards.Card{cards.NewCard(cards.Ace, cards.Hearts), cards.NewCard(cards.Seven, cards.Spades)},
			wantTotal:    18,
			wantSoft:     true,
			wantBJ:       false,
			wantBust:     false,
			wantCanSplit: false,
		},
		{
			name:         "Multiple Aces (A + A + 9)",
			cardsList:    []cards.Card{cards.NewCard(cards.Ace, cards.Hearts), cards.NewCard(cards.Ace, cards.Diamonds), cards.NewCard(cards.Nine, cards.Spades)},
			wantTotal:    21,
			wantSoft:     true,
			wantBJ:       false,
			wantBust:     false,
			wantCanSplit: false,
		},
		{
			name:         "Hard Bust (10 + 6 + 7)",
			cardsList:    []cards.Card{cards.NewCard(cards.Ten, cards.Hearts), cards.NewCard(cards.Six, cards.Diamonds), cards.NewCard(cards.Seven, cards.Spades)},
			wantTotal:    23,
			wantSoft:     false,
			wantBJ:       false,
			wantBust:     true,
			wantCanSplit: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			h := NewHand(10)
			for _, c := range tt.cardsList {
				h.AddCard(c)
			}
			tot, soft := h.Score()
			if tot != tt.wantTotal {
				t.Errorf("Score() total = %d, want %d", tot, tt.wantTotal)
			}
			if soft != tt.wantSoft {
				t.Errorf("Score() soft = %v, want %v", soft, tt.wantSoft)
			}
			if h.IsBlackjack() != tt.wantBJ {
				t.Errorf("IsBlackjack() = %v, want %v", h.IsBlackjack(), tt.wantBJ)
			}
			if h.IsBusted() != tt.wantBust {
				t.Errorf("IsBusted() = %v, want %v", h.IsBusted(), tt.wantBust)
			}
			if h.CanSplit() != tt.wantCanSplit {
				t.Errorf("CanSplit() = %v, want %v", h.CanSplit(), tt.wantCanSplit)
			}
			_ = h.String() // coverage
		})
	}
}

func TestGameEngine_BasicRoundFlows(t *testing.T) {
	rule := rules.VegasStrip()
	engine := NewGameEngine(rule, nil)

	if engine.State != StateWaitingBet {
		t.Fatalf("Expected initial state StateWaitingBet, got %v", engine.State)
	}

	// Invalid Bet
	if err := engine.StartRound(0); err == nil {
		t.Errorf("Expected error starting round with 0 bet")
	}

	// Start valid round
	err := engine.StartRound(100)
	if err != nil {
		t.Fatalf("StartRound failed: %v", err)
	}

	// Active hand
	if engine.ActiveHand() == nil {
		t.Fatalf("ActiveHand should not be nil")
	}

	// If in StateInsuranceOffered, test declining insurance
	if engine.State == StateInsuranceOffered {
		actions := engine.AvailableActions()
		if len(actions) != 2 {
			t.Errorf("Expected 2 insurance actions, got %d", len(actions))
		}
		err = engine.Step(ActionInsuranceDecline)
		if err != nil {
			t.Fatalf("Declining insurance failed: %v", err)
		}
	}

	// If player is in turn
	if engine.State == StatePlayerTurn {
		actions := engine.AvailableActions()
		if len(actions) == 0 {
			t.Errorf("Expected at least 1 action during player turn")
		}
		// Stand to conclude round
		err = engine.Step(ActionStand)
		if err != nil {
			t.Fatalf("Stand failed: %v", err)
		}
	}

	if engine.State != StateRoundResolved {
		t.Fatalf("Expected round to be resolved, got %v", engine.State)
	}

	_ = engine.NetRoundProfit()
}

func TestGameEngine_DoubleDownAndSurrender(t *testing.T) {
	rule := rules.VegasStrip()
	engine := NewGameEngine(rule, nil)

	// Simulate a hand setup manually
	engine.State = StatePlayerTurn
	engine.PlayerHands = []*Hand{NewHand(50)}
	engine.PlayerHands[0].AddCard(cards.NewCard(cards.Five, cards.Hearts))
	engine.PlayerHands[0].AddCard(cards.NewCard(cards.Six, cards.Diamonds)) // 11
	engine.DealerHand = NewHand(0)
	engine.DealerHand.AddCard(cards.NewCard(cards.Seven, cards.Spades))
	engine.DealerHoleCard = cards.NewCard(cards.Ten, cards.Clubs)
	engine.HasHoleCard = true

	// Double Down
	err := engine.Step(ActionDouble)
	if err != nil {
		t.Fatalf("Double down failed: %v", err)
	}

	if !engine.PlayerHands[0].Doubled {
		t.Errorf("Expected hand to be marked doubled")
	}
	if engine.PlayerHands[0].Bet != 100 {
		t.Errorf("Expected doubled bet 100, got %f", engine.PlayerHands[0].Bet)
	}
	if engine.State != StateRoundResolved {
		t.Errorf("Expected round to be resolved after double down, got %v", engine.State)
	}

	// Test Surrender
	engine2 := NewGameEngine(rule, nil)
	engine2.State = StatePlayerTurn
	engine2.PlayerHands = []*Hand{NewHand(50)}
	engine2.PlayerHands[0].AddCard(cards.NewCard(cards.Ten, cards.Hearts))
	engine2.PlayerHands[0].AddCard(cards.NewCard(cards.Six, cards.Diamonds)) // 16
	engine2.DealerHand = NewHand(0)
	engine2.DealerHand.AddCard(cards.NewCard(cards.Ten, cards.Spades))
	engine2.DealerHoleCard = cards.NewCard(cards.Nine, cards.Clubs)
	engine2.HasHoleCard = true

	err = engine2.Step(ActionSurrender)
	if err != nil {
		t.Fatalf("Surrender failed: %v", err)
	}
	if engine2.PlayerHands[0].Status != StatusSurrendered {
		t.Errorf("Expected hand to be surrendered")
	}
	if engine2.PlayerHands[0].NetProfit != -25 {
		t.Errorf("Expected -$25 net profit for surrender, got %f", engine2.PlayerHands[0].NetProfit)
	}
}

func TestGameEngine_SplitHands(t *testing.T) {
	rule := rules.VegasStrip()
	engine := NewGameEngine(rule, nil)

	engine.State = StatePlayerTurn
	engine.PlayerHands = []*Hand{NewHand(50)}
	engine.PlayerHands[0].AddCard(cards.NewCard(cards.Eight, cards.Hearts))
	engine.PlayerHands[0].AddCard(cards.NewCard(cards.Eight, cards.Diamonds))
	engine.DealerHand = NewHand(0)
	engine.DealerHand.AddCard(cards.NewCard(cards.Six, cards.Spades))
	engine.DealerHoleCard = cards.NewCard(cards.Ten, cards.Clubs)
	engine.HasHoleCard = true

	err := engine.Step(ActionSplit)
	if err != nil {
		t.Fatalf("Split failed: %v", err)
	}

	if len(engine.PlayerHands) != 2 {
		t.Fatalf("Expected 2 hands after split, got %d", len(engine.PlayerHands))
	}

	// Play both split hands with Stand
	if engine.State == StatePlayerTurn {
		_ = engine.Step(ActionStand)
	}
	if engine.State == StatePlayerTurn {
		_ = engine.Step(ActionStand)
	}

