138 | 		cardStrs += c.String() + " "
139 | 	}
140 | 	return fmt.Sprintf("[%s] Total: %d%s - %s (Bet: $%.2f)", cardStrs, val, softStr, h.Status.String(), h.Bet)
141 | }
