143 | 
144 | // Insurance responds to insurance offer.
145 | func (g *GameEngine) Insurance(accept bool) error {
146 | 	if g.State != StateInsuranceOffered {
147 | 		return errors.New("insurance is not currently offered")
148 | 	}
