213 | 	hand := g.ActiveHand()
214 | 	if hand == nil || hand.Status != StatusInPlay {
215 | 		return nil
216 | 	}
217 | 
218 | 	actions := []PlayerAction{ActionHit, ActionStand}
219 | 
220 | 	// Double Down
