303 | 	}
304 | }
305 | 
306 | func (g *GameEngine) actionHit(hand *Hand) error {
307 | 	card := g.Shoe.Deal()
308 | 	hand.AddCard(card)
309 | 
310 | 	if hand.IsBusted() {
311 | 		hand.Status = StatusBusted
312 | 		return g.advanceToNextHand()
313 | 	}
314 | 
315 | 	if hand.Total() == 21 {
316 | 		hand.Status = StatusStood
317 | 		return g.advanceToNextHand()
318 | 	}
319 | 
320 | 	return nil
321 | }
322 | 
323 | func (g *GameEngine) actionStand(hand *Hand) error {
324 | 	hand.Status = StatusStood
325 | 	return g.advanceToNextHand()
326 | }
327 | 
328 | func (g *GameEngine) actionDouble(hand *Hand) error {
329 | 	if !hand.CanDouble() {
330 | 		return errors.New("cannot double this hand")
331 | 	}
332 | 
333 | 	hand.Bet *= 2
334 | 	hand.Doubled = true
335 | 	card := g.Shoe.Deal()
336 | 	hand.AddCard(card)
337 | 
338 | 	if hand.IsBusted() {
339 | 		hand.Status = StatusBusted
340 | 	} else {
341 | 		hand.Status = StatusDoubled
342 | 	}
343 | 
344 | 	return g.advanceToNextHand()
345 | }
346 | 
347 | func (g *GameEngine) actionSplit(hand *Hand) error {
348 | 	if !hand.CanSplit() || len(g.PlayerHands) >= g.Rules.MaxSplitHands {
349 | 		return errors.New("cannot split this hand")
350 | 	}
351 | 
352 | 	isAceSplit := hand.Cards[0].IsAce()
353 | 	card1 := hand.Cards[0]
354 | 	card2 := hand.Cards[1]
355 | 
356 | 	// First hand keeps card1, draws 1 new card
357 | 	hand.Cards = []cards.Card{card1}
358 | 	hand.IsSplitHand = true
359 | 	if isAceSplit {
360 | 		hand.FromSplitAces = true
361 | 	}
362 | 	newCard1 := g.Shoe.Deal()
363 | 	hand.AddCard(newCard1)
364 | 
365 | 	// Create second hand with card2, draws 1 new card
366 | 	newHand := NewHand(hand.Bet)
367 | 	newHand.Cards = []cards.Card{card2}
368 | 	newHand.IsSplitHand = true
369 | 	if isAceSplit {
370 | 		newHand.FromSplitAces = true
371 | 	}
372 | 	newCard2 := g.Shoe.Deal()
373 | 	newHand.AddCard(newCard2)
374 | 
375 | 	// Insert second hand right after current hand
376 | 	g.PlayerHands = append(g.PlayerHands[:g.ActiveHandIdx+1], append([]*Hand{newHand}, g.PlayerHands[g.ActiveHandIdx+1:]...)...)
377 | 
378 | 	// If splitting Aces and rule prohibits hitting split Aces, both stand automatically
379 | 	if isAceSplit && !g.Rules.HitSplitAces {
380 | 		hand.Status = StatusStood
381 | 		newHand.Status = StatusStood
382 | 		return g.advanceToNextHand()
383 | 	}
384 | 
385 | 	// If hand total is 21 after receiving card, auto stand
386 | 	if hand.Total() == 21 {
387 | 		hand.Status = StatusStood
