package simulation

import (
	"blackjack/pkg/cards"
	"blackjack/pkg/engine"
	"blackjack/pkg/oracle"
	"blackjack/pkg/rules"
	"context"
	"fmt"
	"math/rand"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// SimConfig configures the Monte Carlo simulation.
type SimConfig struct {
	Rules             rules.RuleSet
	TotalRounds       int64
	Workers           int
	CountingSystem    oracle.CountingSystem
	UseCardCounting   bool
	BaseBet           float64
	Seed              int64
	ProgressFrequency int64 // Update progress every N rounds (0 = disabled)
}

// SimStats aggregates the outcome statistics of the simulation.
type SimStats struct {
	RoundsPlayed       int64         `json:"rounds_played"`
	TotalHandsPlayed   int64         `json:"total_hands_played"`
	TotalAmountWagered float64       `json:"total_amount_wagered"`
	TotalNetProfit     float64       `json:"total_net_profit"`
	ExpectedValue      float64       `json:"expected_value"` // EV per unit wagered (net / wagered)
	HouseEdge          float64       `json:"house_edge"`     // House edge percentage (-EV %)
	PlayerWins         int64         `json:"player_wins"`
	DealerWins         int64         `json:"dealer_wins"`
	Pushes             int64         `json:"pushes"`
	Blackjacks         int64         `json:"blackjacks"`
	Busts              int64         `json:"busts"`
	Surrenders         int64         `json:"surrenders"`
	DoublesWon         int64         `json:"doubles_won"`
	DoublesLost        int64         `json:"doubles_lost"`
	SplitsPlayed       int64         `json:"splits_played"`
	InsurancesWon      int64         `json:"insurances_won"`
	InsurancesLost     int64         `json:"insurances_lost"`
	Duration           time.Duration `json:"duration"`
	RoundsPerSecond    float64       `json:"rounds_per_second"`
}

// ProgressCallback is invoked periodically during simulation runs.
type ProgressCallback func(completedRounds int64, totalRounds int64, currentEV float64)

// Simulator manages concurrent Monte Carlo simulations.
type Simulator struct {
	config SimConfig
}

// NewSimulator creates a new Monte Carlo simulator instance.
func NewSimulator(config SimConfig) *Simulator {
	if config.Workers <= 0 {
		config.Workers = runtime.NumCPU()
	}
	if config.BaseBet <= 0 {
		config.BaseBet = 10.0
	}
	if config.Seed == 0 {
		config.Seed = time.Now().UnixNano()
	}
	return &Simulator{config: config}
}

// workerResult contains stats accumulated by a single worker goroutine.
type workerResult struct {
	roundsPlayed   int64
	handsPlayed    int64
	totalWagered   float64
	netProfit      float64
	playerWins     int64
	dealerWins     int64
	pushes         int64
	blackjacks     int64
	busts          int64
	surrenders     int64
	doublesWon     int64
	doublesLost    int64
	splitsPlayed   int64
	insurancesWon  int64
	insurancesLost int64
}

// Run executes the Monte Carlo simulation concurrently across worker goroutines.
func (s *Simulator) Run(ctx context.Context, progress ProgressCallback) (*SimStats, error) {
	if err := s.config.Rules.Validate(); err != nil {
		return nil, fmt.Errorf("invalid rules: %w", err)
	}

	startTime := time.Now()
	var globalCompleted int64

	roundsPerWorker := s.config.TotalRounds / int64(s.config.Workers)
	remainderRounds := s.config.TotalRounds % int64(s.config.Workers)

	resultsChan := make(chan workerResult, s.config.Workers)
	var wg sync.WaitGroup

	for w := 0; w < s.config.Workers; w++ {
		workerRounds := roundsPerWorker
		if w == 0 {
			workerRounds += remainderRounds
		}

		workerSeed := s.config.Seed + int64(w)*7919 + 17
		wg.Add(1)
		go func(rounds int64, seed int64) {
			defer wg.Done()
			res := s.runWorker(ctx, rounds, seed, &globalCompleted, progress)
			resultsChan <- res
		}(workerRounds, workerSeed)
	}

	wg.Wait()
	close(resultsChan)

	// Aggregate all worker results
	stats := &SimStats{}
	for r := range resultsChan {
		stats.RoundsPlayed += r.roundsPlayed
		stats.TotalHandsPlayed += r.handsPlayed
		stats.TotalAmountWagered += r.totalWagered
		stats.TotalNetProfit += r.netProfit
		stats.PlayerWins += r.playerWins
		stats.DealerWins += r.dealerWins
		stats.Pushes += r.pushes
		stats.Blackjacks += r.blackjacks
		stats.Busts += r.busts
		stats.Surrenders += r.surrenders
		stats.DoublesWon += r.doublesWon
		stats.DoublesLost += r.doublesLost
		stats.SplitsPlayed += r.splitsPlayed
		stats.InsurancesWon += r.insurancesWon
		stats.InsurancesLost += r.insurancesLost
	}

	stats.Duration = time.Since(startTime)
	if stats.Duration > 0 {
		stats.RoundsPerSecond = float64(stats.RoundsPlayed) / stats.Duration.Seconds()
	}

	if stats.TotalAmountWagered > 0 {
		stats.ExpectedValue = stats.TotalNetProfit / stats.TotalAmountWagered
		stats.HouseEdge = -stats.ExpectedValue * 100.0 // House edge is negative player EV %
	}

	return stats, nil
}

// runWorker executes a slice of rounds in an isolated goroutine without locks.
func (s *Simulator) runWorker(
	ctx context.Context,
	rounds int64,
	seed int64,
	globalCompleted *int64,
	progress ProgressCallback,
) workerResult {
	res := workerResult{}
	rng := rand.New(rand.NewSource(seed))

	counter := oracle.NewCardCounter(s.config.CountingSystem, s.config.Rules.Decks)

	shoe := cards.NewShoe(
		s.config.Rules.Decks,
		cards.WithCutCardPenetration(s.config.Rules.DeckPenetration),
		cards.WithCustomRNG(rng),
		cards.WithDealListener(func(c cards.Card) {
			counter.ObserveCard(c)
		}),
	)

	advisor := oracle.NewStrategyAdvisor(s.config.Rules)

	for i := int64(0); i < rounds; i++ {
		select {
		case <-ctx.Done():
			return res
		default:
		}

		if shoe.NeedsShuffle() {
			shoe.ResetAndShuffle()
			counter.Reset()
		}

		// Calculate bet size
		bet := s.config.BaseBet
		tc := counter.TrueCount()
		if s.config.UseCardCounting {
			mult := counter.RecommendedBetMultiplier()
			bet = s.config.BaseBet * float64(mult)
		}

		game := engine.NewGameEngine(s.config.Rules, shoe)

		err := game.StartRound(bet)
		if err != nil {
			continue
		}

		// Handle Insurance offer
		if game.State == engine.StateInsuranceOffered {
			accept, _ := advisor.AdviseInsurance(tc)
			_ = game.Insurance(accept)
		}

		// Player decision loop
		for game.State == engine.StatePlayerTurn {
			hand := game.ActiveHand()
			if hand == nil {
				break
			}

			dealerUpcard := game.DealerUpcard()
			rec := advisor.Advise(hand, dealerUpcard, tc)

			// Try to execute recommended action, falling back to basic alternatives if not permitted
			var actErr error
			switch rec.Action {
			case engine.ActionSurrender:
				actErr = game.Step(engine.ActionSurrender)
				if actErr != nil {
					actErr = game.Step(engine.ActionHit)
				}
			case engine.ActionSplit:
				actErr = game.Step(engine.ActionSplit)
				if actErr != nil {
					if hand.Total() >= 17 {
						actErr = game.Step(engine.ActionStand)
					} else {
						actErr = game.Step(engine.ActionHit)
					}
				}
			case engine.ActionDouble:
				actErr = game.Step(engine.ActionDouble)
				if actErr != nil {
					actErr = game.Step(engine.ActionHit)
				}
			case engine.ActionHit:
				actErr = game.Step(engine.ActionHit)
			case engine.ActionStand:
				actErr = game.Step(engine.ActionStand)
			default:
				actErr = game.Step(engine.ActionStand)
			}

			if actErr != nil {
				_ = game.Step(engine.ActionStand)
			}
		}

		// Tally round statistics
		res.roundsPlayed++
		res.netProfit += game.NetRoundProfit()

		for _, h := range game.PlayerHands {
			res.handsPlayed++
			res.totalWagered += h.Bet

			if h.Status == engine.StatusBusted {
				res.busts++
			}
			if h.Status == engine.StatusSurrendered {
				res.surrenders++
			}
			if h.IsSplitHand {
				res.splitsPlayed++
			}
			if h.Doubled {
				if h.NetProfit > 0 {
					res.doublesWon++
				} else if h.NetProfit < 0 {
					res.doublesLost++
				}
			}

			if h.NetProfit > 0 {
				res.playerWins++
				if h.Status == engine.StatusBlackjack {
					res.blackjacks++
				}
			} else if h.NetProfit < 0 {
				res.dealerWins++
			} else {
				res.pushes++
			}

			if h.InsuranceBet > 0 {
				res.totalWagered += h.InsuranceBet
				if h.InsuranceWon {
					res.insurancesWon++
				} else {
					res.insurancesLost++
				}
			}
		}

		// Progress update
		if progress != nil && s.config.ProgressFrequency > 0 && i%s.config.ProgressFrequency == 0 {
			completed := atomic.AddInt64(globalCompleted, s.config.ProgressFrequency)
			currentEV := 0.0
			if res.totalWagered > 0 {
				currentEV = res.netProfit / res.totalWagered
			}
			progress(completed, s.config.TotalRounds, currentEV)
		}
	}

	return res
}

package simulation

import (
	"blackjack/pkg/oracle"
	"blackjack/pkg/rules"
	"context"
	"testing"
	"time"
)

func TestSimulator_BasicStrategyEV(t *testing.T) {
	config := SimConfig{
		Rules:             rules.VegasStrip(),
		TotalRounds:       20000,
		Workers:           4,
		CountingSystem:    oracle.HiLo,
		UseCardCounting:   false,
		BaseBet:           10.0,
		Seed:              42,
		ProgressFrequency: 5000,
	}

	sim := NewSimulator(config)

	var lastProgress int64
	progressCB := func(completed int64, total int64, ev float64) {
		lastProgress = completed
	}

	stats, err := sim.Run(context.Background(), progressCB)
	if err != nil {
		t.Fatalf("Simulation failed: %v", err)
	}

	if stats.RoundsPlayed != 20000 {
		t.Errorf("Expected 20000 rounds played, got %d", stats.RoundsPlayed)
	}
	if stats.TotalAmountWagered <= 0 {
		t.Errorf("Expected positive wagered amount, got %f", stats.TotalAmountWagered)
	}
	if stats.TotalHandsPlayed < stats.RoundsPlayed {
		t.Errorf("Hands played (%d) should be >= rounds played (%d)", stats.TotalHandsPlayed, stats.RoundsPlayed)
	}

	// Basic strategy house edge in Vegas Strip is typically ~0.3% to 1.5%
	t.Logf("EV: %.4f, House Edge: %.2f%%, Net Profit: $%.2f over %d rounds (%.1f rps)",
		stats.ExpectedValue, stats.HouseEdge, stats.TotalNetProfit, stats.RoundsPlayed, stats.RoundsPerSecond)

	if stats.HouseEdge < -10.0 || stats.HouseEdge > 10.0 {
		t.Errorf("Unrealistic house edge: %.2f%%", stats.HouseEdge)
	}
}

func TestSimulator_CardCountingEdge(t *testing.T) {
	// Card counting with Hi-Lo bet spread should outperform flat betting
	config := SimConfig{
		Rules:             rules.AtlanticCity(),
		TotalRounds:       20000,
		Workers:           4,
		CountingSystem:    oracle.HiLo,
		UseCardCounting:   true,
		BaseBet:           10.0,
		Seed:              12345,
		ProgressFrequency: 0,
	}

	sim := NewSimulator(config)
	stats, err := sim.Run(context.Background(), nil)
	if err != nil {
		t.Fatalf("Simulation with counting failed: %v", err)
	}

	if stats.RoundsPlayed != 20000 {
		t.Errorf("Expected 20000 rounds, got %d", stats.RoundsPlayed)
	}
	t.Logf("Card Counting Net Profit: $%.2f, Total Wagered: $%.2f, EV: %.4f",
		stats.TotalNetProfit, stats.TotalAmountWagered, stats.ExpectedValue)
}

func TestSimulator_ContextCancellation(t *testing.T) {
	config := SimConfig{
		Rules:       rules.VegasStrip(),
		TotalRounds: 1000000, // Large run
		Workers:     2,
		BaseBet:     10.0,
		Seed:        999,
	}

	sim := NewSimulator(config)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()

	stats, err := sim.Run(ctx, nil)
	if err != nil {
		t.Fatalf("Expected clean cancellation, got error: %v", err)
	}

	if stats.RoundsPlayed >= 1000000 {
		t.Errorf("Simulation did not stop early on context cancellation")
	}
}

func TestSimulator_InvalidRules(t *testing.T) {
	invalidRule := rules.VegasStrip()
	invalidRule.Decks = 0 // Invalid

	config := SimConfig{
		Rules:       invalidRule,
		TotalRounds: 100,
	}

	sim := NewSimulator(config)
	_, err := sim.Run(context.Background(), nil)
	if err == nil {
		t.Error("Expected error on invalid rules, got nil")
	}
}

func BenchmarkMonteCarlo10kHands(b *testing.B) {
	config := SimConfig{
		Rules:           rules.VegasStrip(),
		TotalRounds:     10000,
		Workers:         4,
		CountingSystem:  oracle.HiLo,
		UseCardCounting: true,
		BaseBet:         10.0,
		Seed:            101,
	}
	sim := NewSimulator(config)

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_, _ = sim.Run(context.Background(), nil)
	}
}

package ui

import (
	"blackjack/pkg/cards"
	"blackjack/pkg/engine"
	"blackjack/pkg/oracle"
	"fmt"
	"strings"
)

// ANSI color codes for terminal rendering.
const (
	Reset   = "\033[0m"
	Bold    = "\033[1m"
	Dim     = "\033[2m"
	Red     = "\033[31m"
	Green   = "\033[32m"
	Yellow  = "\033[33m"
	Blue    = "\033[34m"
	Magenta = "\033[35m"
	Cyan    = "\033[36m"
	White   = "\033[37m"
	BgBlack = "\033[40m"
)

// CardRenderer renders ASCII playing cards.
type CardRenderer struct {
	UseColors bool
}

// NewCardRenderer returns a new CardRenderer.
func NewCardRenderer(useColors bool) *CardRenderer {
	return &CardRenderer{UseColors: useColors}
}

// RenderCard returns the 5-line ASCII art representation of a single card.
// Example:
// ┌─────────┐
// │ A       │
// │    ♠    │
// │       A │
// └─────────┘
func (r *CardRenderer) RenderCard(c cards.Card, hidden bool) []string {
	if hidden {
		return []string{
			"┌─────────┐",
			"│░░░░░░░░░│",
			"│░░░ 🂠 ░░░│",
			"│░░░░░░░░░│",
			"└─────────┘",
		}
	}

	rankStr := c.Rank.String()
	suitStr := c.Suit.String()

	leftRank := fmt.Sprintf("%-2s", rankStr)
	rightRank := fmt.Sprintf("%2s", rankStr)

	suitColor := White
	if r.UseColors {
		if c.Suit == cards.Hearts || c.Suit == cards.Diamonds {
			suitColor = Red
		} else {
			suitColor = Cyan
		}
	}

	coloredSuit := suitStr
	if r.UseColors {
		coloredSuit = fmt.Sprintf("%s%s%s", suitColor, suitStr, Reset)
	}

	line0 := "┌─────────┐"
	line1 := fmt.Sprintf("│ %s      │", leftRank)
	line2 := fmt.Sprintf("│    %s    │", coloredSuit)
	line3 := fmt.Sprintf("│      %s │", rightRank)
	line4 := "└─────────┘"

	return []string{line0, line1, line2, line3, line4}
}

// RenderHandMultiLine renders multiple cards horizontally side-by-side.
func (r *CardRenderer) RenderHandMultiLine(handCards []cards.Card, hideHoleCard bool) string {
	if len(handCards) == 0 {
		return "[Empty Hand]"
	}

	cardLines := make([][]string, len(handCards))
	for i, c := range handCards {
		isHidden := hideHoleCard && i == 1
		cardLines[i] = r.RenderCard(c, isHidden)
	}

	var sb strings.Builder
	for lineIdx := 0; lineIdx < 5; lineIdx++ {
		for cardIdx := 0; cardIdx < len(handCards); cardIdx++ {
			sb.WriteString(cardLines[cardIdx][lineIdx])
			sb.WriteString("  ")
		}
		sb.WriteString("\n")
	}

	return sb.String()
}

// FormatOracleHUD formats the card counting and real-time basic strategy recommendations.
func FormatOracleHUD(counter *oracle.CardCounter, advisor *oracle.StrategyAdvisor, activeHand *engine.Hand, dealerUpcard cards.Card) string {
	var sb strings.Builder

	rc := counter.RunningCount()
	tc := counter.TrueCount()
	pen := counter.ShoePenetration() * 100.0
	remDecks := counter.RemainingDecks()
	betMult := counter.RecommendedBetMultiplier()

	sb.WriteString(fmt.Sprintf("%s=== 🔮 CARD COUNTING ORACLE HUD ===%s\n", Bold+Cyan, Reset))
	sb.WriteString(fmt.Sprintf("  System: %-15s | Running Count (RC): %+d\n", counter.SystemName(), rc))
	sb.WriteString(fmt.Sprintf("  True Count (TC): %+.2f   | Remaining Decks: %.2f\n", tc, remDecks))
	sb.WriteString(fmt.Sprintf("  Shoe Penetration: %5.1f%% | Kelly Bet Sizing: %dx Base Bet\n", pen, betMult))

	if activeHand != nil {
		rec := advisor.Advise(activeHand, dealerUpcard, tc)
		actionColor := Green
		switch rec.Action {
		case engine.ActionHit:
			actionColor = Yellow
		case engine.ActionDouble:
			actionColor = Cyan
		case engine.ActionSplit:
			actionColor = Magenta
		case engine.ActionSurrender:
			actionColor = Red
		case engine.ActionStand:
			actionColor = Blue
		}
		sb.WriteString(fmt.Sprintf("  Advisor Recommendation: %s%s%s (%s)\n", Bold+actionColor, rec.Action.String(), Reset, rec.Description))
	}
	sb.WriteString(fmt.Sprintf("%s=================================%s\n", Dim+Cyan, Reset))

	return sb.String()
}

// FormatTableState generates a full ASCII snapshot of the current blackjack table.
func FormatTableState(
	r *CardRenderer,
	game *engine.GameEngine,
	counter *oracle.CardCounter,
	advisor *oracle.StrategyAdvisor,
	showOracle bool,
) string {
	var sb strings.Builder

	sb.WriteString("\n" + strings.Repeat("═", 60) + "\n")
	sb.WriteString(fmt.Sprintf("  TABLE RULES: %s (%d Decks, %s, %s)\n",
		game.Rules.Name, game.Rules.Decks,
		map[bool]string{true: "H17", false: "S17"}[game.Rules.DealerHitsSoft17],
		game.Rules.BlackjackPayout.String()))
	sb.WriteString(strings.Repeat("═", 60) + "\n\n")

	// 1. Dealer Hand
	hideDealerHole := game.HasHoleCard && (game.State == engine.StatePlayerTurn || game.State == engine.StateInsuranceOffered)
	dealerDisplayCards := game.DealerHand.Cards
	if hideDealerHole && game.HasHoleCard {
		dealerDisplayCards = []cards.Card{game.DealerHand.Cards[0], game.DealerHoleCard}
	}

	dealerScoreStr := "?"
	if !hideDealerHole {
		tot, isSoft := game.DealerHand.Score()
		softStr := ""
		if isSoft && tot < 21 {
			softStr = " (soft)"
		}
		dealerScoreStr = fmt.Sprintf("%d%s - %s", tot, softStr, game.DealerHand.Status.String())
	}

	sb.WriteString(fmt.Sprintf("%s🏦 DEALER HAND%s (Score: %s)\n", Bold+Yellow, Reset, dealerScoreStr))
	sb.WriteString(r.RenderHandMultiLine(dealerDisplayCards, hideDealerHole))
	sb.WriteString("\n")

	// 2. Player Hands
	sb.WriteString(fmt.Sprintf("%s👤 PLAYER HANDS%s\n", Bold+Green, Reset))
	for i, hand := range game.PlayerHands {
		prefix := "  "
		if i == game.ActiveHandIdx && game.State == engine.StatePlayerTurn {
			prefix = "👉"
		}
		tot, isSoft := hand.Score()
		softStr := ""
		if isSoft && tot < 21 {
			softStr = " (soft)"
		}
		sb.WriteString(fmt.Sprintf("%s Hand #%d: Bet: $%.2f | Total: %d%s | Status: %s\n",
			prefix, i+1, hand.Bet, tot, softStr, hand.Status.String()))
		sb.WriteString(r.RenderHandMultiLine(hand.Cards, false))
	}

	// 3. Oracle HUD
	if showOracle && counter != nil && advisor != nil {
		sb.WriteString("\n")
		sb.WriteString(FormatOracleHUD(counter, advisor, game.ActiveHand(), game.DealerUpcard()))
	}

	return sb.String()
}

package ui

import (
	"blackjack/pkg/cards"
	"blackjack/pkg/engine"
	"blackjack/pkg/oracle"
	"blackjack/pkg/rules"
	"strings"
	"testing"
)

func TestRenderCard(t *testing.T) {
	renderer := NewCardRenderer(false) // No colors to make testing output easier

	card := cards.Card{Rank: cards.Ace, Suit: cards.Spades}
	lines := renderer.RenderCard(card, false)

	if len(lines) != 5 {
		t.Fatalf("expected 5 lines, got %d", len(lines))
	}

	expectedLine1 := "│ A       │"
	if lines[1] != expectedLine1 {
		t.Errorf("expected line 1 to be %q, got %q", expectedLine1, lines[1])
	}

	hiddenLines := renderer.RenderCard(card, true)
	if len(hiddenLines) != 5 {
		t.Fatalf("expected 5 hidden lines, got %d", len(hiddenLines))
	}
	if hiddenLines[1] != "│░░░░░░░░░│" {
		t.Errorf("expected hidden line 1 to be '│░░░░░░░░░│', got %q", hiddenLines[1])
	}
}

func TestRenderCard_WithColors(t *testing.T) {
	renderer := NewCardRenderer(true)
	card := cards.Card{Rank: cards.Ten, Suit: cards.Hearts}
	lines := renderer.RenderCard(card, false)

	// ♥ should be colored red
	if !strings.Contains(lines[2], Red) {
		t.Errorf("expected red color for hearts, line: %q", lines[2])
	}
}

func TestRenderHandMultiLine(t *testing.T) {
	renderer := NewCardRenderer(false)

	t.Run("EmptyHand", func(t *testing.T) {
		res := renderer.RenderHandMultiLine([]cards.Card{}, false)
		if res != "[Empty Hand]" {
			t.Errorf("expected '[Empty Hand]', got %q", res)
		}
	})

	t.Run("TwoCards", func(t *testing.T) {
		hand := []cards.Card{
			{Rank: cards.Ace, Suit: cards.Spades},
			{Rank: cards.Ten, Suit: cards.Hearts},
		}
		res := renderer.RenderHandMultiLine(hand, false)
		if !strings.Contains(res, "A") || !strings.Contains(res, "10") {
			t.Errorf("output missing card ranks, got:\n%s", res)
		}
		lines := strings.Split(res, "\n")
		// 5 lines + 1 empty line at the end
		if len(lines) != 6 {
			t.Errorf("expected 6 lines in multiline render, got %d", len(lines))
		}
	})

	t.Run("HideHoleCard", func(t *testing.T) {
		hand := []cards.Card{
			{Rank: cards.Ace, Suit: cards.Spades},
			{Rank: cards.Ten, Suit: cards.Hearts},
		}
		res := renderer.RenderHandMultiLine(hand, true)
		if strings.Contains(res, "10") {
			t.Errorf("output should not contain hidden card rank, got:\n%s", res)
		}
		if !strings.Contains(res, "░░░") {
			t.Errorf("output missing hidden card pattern, got:\n%s", res)
		}
	})
}

func TestFormatOracleHUD(t *testing.T) {
	counter := oracle.NewCardCounter(1)
	advisor := oracle.NewStrategyAdvisor(rules.VegasStrip())

	hand := &engine.Hand{
		Cards: []cards.Card{
			{Rank: cards.Ten, Suit: cards.Spades},
			{Rank: cards.Six, Suit: cards.Hearts},
		},
	}
	dealerUpcard := cards.Card{Rank: cards.Ten, Suit: cards.Diamonds}

	res := FormatOracleHUD(counter, advisor, hand, dealerUpcard)
	if !strings.Contains(res, "Running Count (RC):") {
		t.Errorf("missing RC in HUD:\n%s", res)
	}
	if !strings.Contains(res, "Advisor Recommendation:") {
		t.Errorf("missing Advisor Recommendation in HUD:\n%s", res)
	}
	if !strings.Contains(res, "Surrender") && !strings.Contains(res, "Hit") {
		// 16 vs 10 is usually Surrender/Hit
		t.Errorf("expected recommendation to contain action, got:\n%s", res)
	}
}

func TestFormatTableState(t *testing.T) {
	renderer := NewCardRenderer(false)
	game := engine.NewGameEngine(rules.VegasStrip())
	shoe := cards.NewShoe(1)
	shoe.Cards = []cards.Card{
		{Rank: cards.Ten, Suit: cards.Spades}, // Dealer up
		{Rank: cards.Ten, Suit: cards.Hearts}, // Player 1
		{Rank: cards.Six, Suit: cards.Diamonds}, // Dealer down
		{Rank: cards.Six, Suit: cards.Clubs}, // Player 2
	}

	game.StartRound(shoe, []float64{10.0})
	counter := oracle.NewCardCounter(1)
	advisor := oracle.NewStrategyAdvisor(game.Rules)

	res := FormatTableState(renderer, game, counter, advisor, true)
	if !strings.Contains(res, "DEALER HAND") {
		t.Errorf("missing dealer hand section:\n%s", res)
	}
	if !strings.Contains(res, "PLAYER HANDS") {
		t.Errorf("missing player hand section:\n%s", res)
	}
	if !strings.Contains(res, "ORACLE HUD") {
		t.Errorf("missing oracle HUD section:\n%s", res)
	}
}

