 20 | 		return "Hi-Lo"
 21 | 	case KO:
 22 | 		return "KO (Knock-Out)"
 23 | 	case OmegaII:
 24 | 		return "Omega II"
 25 | 	default:
 26 | 		return "Unknown"
 27 | 	}
 28 | }
 29 | 
 30 | // CardCounter tracks seen cards and computes running count, true count, and shoe stats.
 31 | type CardCounter struct {
 32 | 	system         CountingSystem
 33 | 	initialDecks   int
 34 | 	runningCount   int
 35 | 	aceSideCount   int
 36 | 	totalCardsSeen int
 37 | }
 38 | 
 39 | // NewCardCounter initializes a card counter for a given system and deck count.
 40 | func NewCardCounter(system CountingSystem, initialDecks int) *CardCounter {
 41 | 	if initialDecks < 1 {
 42 | 		initialDecks = 1
 43 | 	}
 44 | 
 45 | 	cc := &CardCounter{
 46 | 		system:       system,
 47 | 		initialDecks: initialDecks,
 48 | 	}
 49 | 	cc.Reset()
 50 | 	return cc
 51 | }
 52 | 
 53 | // Reset resets running count and stats based on the system starting count (e.g. KO initial count).
 54 | func (cc *CardCounter) Reset() {
 55 | 	cc.totalCardsSeen = 0
 56 | 	cc.aceSideCount = 0
 57 | 
 58 | 	switch cc.system {
 59 | 	case KO:
 60 | 		// KO initial running count = 4 - (4 * decks)
 61 | 		cc.runningCount = 4 - (4 * cc.initialDecks)
 62 | 	default:
 63 | 		cc.runningCount = 0
 64 | 	}
 65 | }
 66 | 
 67 | // CardValue returns the point count value of a single card under current system.
 68 | func (cc *CardCounter) CardValue(card cards.Card) int {
 69 | 	switch cc.system {
 70 | 	case HiLo:
 71 | 		// 2-6: +1, 7-9: 0, 10-A: -1
 72 | 		switch card.Rank {
 73 | 		case cards.Two, cards.Three, cards.Four, cards.Five, cards.Six:
 74 | 			return 1
 75 | 		case cards.Seven, cards.Eight, cards.Nine:
 76 | 			return 0
 77 | 		case cards.Ten, cards.Jack, cards.Queen, cards.King, cards.Ace:
 78 | 			return -1
 79 | 		}
 80 | 	case KO:
 81 | 		// 2-7: +1, 8-9: 0, 10-A: -1
 82 | 		switch card.Rank {
 83 | 		case cards.Two, cards.Three, cards.Four, cards.Five, cards.Six, cards.Seven:
 84 | 			return 1
 85 | 		case cards.Eight, cards.Nine:
 86 | 			return 0
 87 | 		case cards.Ten, cards.Jack, cards.Queen, cards.King, cards.Ace:
 88 | 			return -1
 89 | 		}
 90 | 	case OmegaII:
 91 | 		// 2,3,7: +1; 4,5,6: +2; 9: -1; 10,J,Q,K: -2; 8,A: 0
 92 | 		switch card.Rank {
 93 | 		case cards.Two, cards.Three, cards.Seven:
 94 | 			return 1
 95 | 		case cards.Four, cards.Five, cards.Six:
 96 | 			return 2
 97 | 		case cards.Nine:
 98 | 			return -1
 99 | 		case cards.Ten, cards.Jack, cards.Queen, cards.King:
100 | 			return -2
101 | 		case cards.Eight, cards.Ace:
102 | 			return 0
103 | 		}
104 | 	}
105 | 	return 0
106 | }
107 | 
108 | // ObserveCard feeds a revealed card into the counting engine.
109 | func (cc *CardCounter) ObserveCard(card cards.Card) {
110 | 	cc.totalCardsSeen++
111 | 	cc.runningCount += cc.CardValue(card)
112 | 	if card.IsAce() {
113 | 		cc.aceSideCount++
114 | 	}
115 | }
116 | 
117 | // RunningCount returns the current running count.
118 | func (cc *CardCounter) RunningCount() int {
119 | 	return cc.runningCount
120 | }
121 | 
122 | // RemainingDecks computes remaining decks based on total initial decks and cards seen.
123 | func (cc *CardCounter) RemainingDecks() float64 {
124 | 	totalCards := cc.initialDecks * 52
125 | 	remaining := totalCards - cc.totalCardsSeen
126 | 	decks := float64(remaining) / 52.0
127 | 	if decks < 0.5 {
128 | 		return 0.5 // minimum floor to avoid extreme division
129 | 	}
130 | 	return decks
131 | }
132 | 
133 | // TrueCount returns the True Count (RC / Remaining Decks). For unbalanced KO, returns Running Count.
134 | func (cc *CardCounter) TrueCount() float64 {
135 | 	if cc.system == KO {
136 | 		// KO is an unbalanced count; key count pivots at -4 or 0
137 | 		return float64(cc.runningCount)
138 | 	}
139 | 	remDecks := cc.RemainingDecks()
140 | 	return float64(cc.runningCount) / remDecks
141 | }
142 | 
143 | // TrueCountRounded returns True Count rounded to nearest integer (standard convention).
144 | func (cc *CardCounter) TrueCountRounded() int {
145 | 	tc := cc.TrueCount()
146 | 	return int(math.Round(tc))
147 | }
148 | 
149 | // ShoePenetration returns the fraction of total cards seen (0.0 to 1.0).
150 | func (cc *CardCounter) ShoePenetration() float64 {
151 | 	totalCards := cc.initialDecks * 52
152 | 	if totalCards == 0 {
153 | 		return 0
154 | 	}
155 | 	return float64(cc.totalCardsSeen) / float64(totalCards)
156 | }
157 | 
158 | // RecommendedBetMultiplier advises how many standard betting units to wager based on Kelly criterion / True Count.
159 | func (cc *CardCounter) RecommendedBetMultiplier() int {
160 | 	tc := cc.TrueCount()
161 | 	if tc <= 1.0 {
162 | 		return 1 // Minimum bet unit
163 | 	} else if tc <= 2.0 {
164 | 		return 2
165 | 	} else if tc <= 3.0 {
166 | 		return 4
167 | 	} else if tc <= 4.0 {
168 | 		return 6
169 | 	} else {
170 | 		return 8 // Max bet spread unit
171 | 	}
172 | }
